await ctx.addCookies([{ name: 'mo_uid', value: users.find((u) => u.email === 'claudia@kaori.jp').id, url: BASE }]);
const page = await ctx.newPage();
page.on('pageerror', (e) => console.log('pageerror:', e.message));
await page.goto(`${BASE}/flow`);
await page.locator('[data-testid="flow-template"][data-template="blank"]').click({ timeout: 90000 });
await page.waitForURL(/\/flow\/[0-9a-f-]{36}/);
await page.locator('[data-testid="flow-node"][data-text="First step"]').waitFor({ timeout: 90000 });
await page.locator('[data-testid="shape-tile"][data-shape="decision"]').click();
await page.locator('[data-testid="flow-node"][data-text="Decision?"]').waitFor();
console.log('added; nodes', await page.getByTestId('flow-node').count());
await page.waitForTimeout(1000);
await page.locator('[data-testid="flow-node"][data-text="Decision?"]').click();
await page.keyboard.press('Delete');
await page.locator('[data-testid="flow-node"][data-text="Decision?"]').waitFor({ state: 'detached' });
await page.waitForTimeout(600);
await page.keyboard.press('Control+z');
await page.waitForTimeout(1000);
console.log('after undo nodes', await page.getByTestId('flow-node').count(), 'decision', await page.locator('[data-testid="flow-node"][data-text="Decision?"]').count());
