import { chromium } from 'playwright';
const BASE = 'http://localhost:3010', API = 'http://localhost:4000';
const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1500, height: 900 } });
const users = await (await ctx.request.get(`${BASE}/api/users`)).json();
const ken = users.find((u) => u.email === 'ken@kaori.jp').id;
await ctx.addCookies([{ name: 'mo_uid', value: ken, url: BASE }]);
const deck = await (await fetch(`${API}/resources`, { method: 'POST', headers: { 'x-user-id': ken, 'content-type': 'application/json' }, body: JSON.stringify({ name: 'Undo probe', type: 'presentation' }) })).json();
const page = await ctx.newPage();
await page.goto(`${BASE}/slides/${deck.id}`);
await page.locator('[data-testid="slide-thumb"]').first().waitFor({ timeout: 90000 });
await page.waitForTimeout(1500);
const size = () => page.getByLabel('Font size').inputValue().catch(() => '?');
const hit = page.locator('[data-hit]').first();
await hit.click();
console.log('selected, size', await size());
await page.getByLabel('Font size').selectOption('72');
await page.waitForTimeout(500);
console.log('after 72', await size());
await page.getByRole('button', { name: 'Undo (Ctrl+Z)' }).click();
await page.waitForTimeout(500);
await hit.click();
console.log('after undo button', await size());
await page.getByLabel('Font size').selectOption('20');
await page.waitForTimeout(500);
await page.locator('[data-testid="slide-canvas"]').click({ position: { x: 5, y: 5 } });
await page.keyboard.press('Control+z');
await page.waitForTimeout(500);
await hit.click();
console.log('after ctrl+z', await size());
await fetch(`${API}/resources/${deck.id}/trash`, { method: 'POST', headers: { 'x-user-id': ken } });
await fetch(`${API}/resources/${deck.id}`, { method: 'DELETE', headers: { 'x-user-id': ken } });
await browser.close();
EOF
