// node contact.cjs <deckId> <outDir> <out.png>: exports every slide at 0.5× and lays them out 5 across.
const sharp = require('E:/office/node_modules/sharp');
const JSZip = require('E:/office/node_modules/jszip');
const fs = require('fs');
(async () => {
  const [id, dir, out] = process.argv.slice(2);
  const API = 'http://localhost:4000';
  const u = (await (await fetch(API + '/users')).json()).find((x) => x.email === 'claudia@kaori.jp').id;
  const res = await fetch(`${API}/resources/${id}/export?format=png&scale=0.5`, { headers: { 'x-user-id': u } });
  const zip = await JSZip.loadAsync(Buffer.from(await res.arrayBuffer()));
  const names = Object.keys(zip.files).sort();
  const tiles = [];
  for (const n of names) {
    const buf = await zip.files[n].async('nodebuffer');
    fs.writeFileSync(`${dir}/${n.replace(/^.* - slide /, 'slide-')}`, buf);
    tiles.push(await sharp(buf).resize(384, 216).png().toBuffer());
  }
  const cols = 5, w = 384, h = 216, gap = 8;
  const rows = Math.ceil(tiles.length / cols);
  await sharp({ create: { width: cols * (w + gap) + gap, height: rows * (h + gap) + gap, channels: 3, background: '#e2e8f0' } })
    .composite(tiles.map((t, i) => ({ input: t, left: gap + (i % cols) * (w + gap), top: gap + Math.floor(i / cols) * (h + gap) })))
    .png().toFile(out);
  console.log(tiles.length, 'slides');
})();
EOF
